"""Google Gemini provider (structured JSON output, validated by ``AgentTurn``).

The model only classifies and extracts. Its reply is parsed as JSON, normalised defensively
(length limits) and validated with ``AgentTurn.model_validate``; one corrective retry is made
before ``LLMOutputError``. Error messages are fixed, safe strings: the API key, request bodies
and raw SDK exceptions are never surfaced or logged.

SDK notes (google-genai 2.x): ``ThinkingConfig(thinking_level=ThinkingLevel.LOW)`` and
``response_mime_type="application/json"`` with ``response_json_schema=<dict>``.
"""

from __future__ import annotations

import json
import logging
import time
from collections.abc import Mapping
from typing import Any, Protocol

import httpx
from pydantic import BaseModel, ConfigDict, ValidationError

from app.config import Settings
from app.domain.enums import ClaimType, DayPart, LeaveType, RequestStatus, RequestType
from app.llm.base import LLMError, LLMOutputError
from app.llm.prompts import CORRECTION_TEMPLATE, SYSTEM_PROMPT, build_user_prompt
from app.llm.schemas import AgentTurn, Intent, LLMContext

logger = logging.getLogger(__name__)

TOTAL_TIMEOUT_SECONDS = 20.0
MAX_OUTPUT_TOKENS = 2048


# --- Thin wire schema: what Gemini is asked to produce (dates as ISO strings, no constraints) ---
class _WireLeave(BaseModel):
    model_config = ConfigDict(extra="ignore")

    leave_type: LeaveType | None = None
    start_date: str | None = None
    end_date: str | None = None
    start_day_part: DayPart | None = None
    end_day_part: DayPart | None = None


class _WireClaim(BaseModel):
    model_config = ConfigDict(extra="ignore")

    claim_type: ClaimType | None = None
    amount: float | None = None
    currency: str | None = None
    receipt_date: str | None = None


class _WireRef(BaseModel):
    model_config = ConfigDict(extra="ignore")

    request_id: int | None = None
    request_type: RequestType | None = None
    hint: str | None = None


class _WireStatusQuery(BaseModel):
    model_config = ConfigDict(extra="ignore")

    request_type: RequestType | None = None
    request_id: int | None = None
    status: RequestStatus | None = None


class WireTurn(BaseModel):
    """JSON shape requested from Gemini; converted into ``AgentTurn`` by validation."""

    model_config = ConfigDict(extra="ignore")

    intent: Intent
    request_type: RequestType | None = None
    leave: _WireLeave | None = None
    claim: _WireClaim | None = None
    target: _WireRef | None = None
    status_query: _WireStatusQuery | None = None
    ambiguities: list[str] = []
    followup_question: str | None = None
    confidence: float | None = None
    rationale: str | None = None


def _inline_refs(node: Any, defs: Mapping[str, Any]) -> Any:
    """Inline ``$ref`` and drop keywords Gemini does not need (title, default, $defs)."""
    if isinstance(node, dict):
        if "$ref" in node:
            return _inline_refs(defs[node["$ref"].rsplit("/", 1)[-1]], defs)
        return {
            key: _inline_refs(value, defs)
            for key, value in node.items()
            if key not in {"title", "default", "$defs"}
        }
    if isinstance(node, list):
        return [_inline_refs(item, defs) for item in node]
    return node


def build_response_schema() -> dict[str, Any]:
    raw = WireTurn.model_json_schema()
    return _inline_refs(raw, raw.get("$defs", {}))


RESPONSE_SCHEMA: dict[str, Any] = build_response_schema()


class _ModelsAPI(Protocol):
    def generate_content(self, *, model: str, contents: Any, config: Any) -> Any: ...


class GeminiClient(Protocol):
    """The slice of ``google.genai.Client`` we use (also implemented by test doubles)."""

    models: _ModelsAPI


def _strip_fences(text: str) -> str:
    text = text.strip()
    if text.startswith("```"):
        text = text.split("\n", 1)[1] if "\n" in text else ""
        if text.rstrip().endswith("```"):
            text = text.rstrip()[:-3]
    return text.strip()


def _limit(value: Any, size: int) -> Any:
    return value[:size] if isinstance(value, str) else value


def normalise_output(data: dict[str, Any]) -> dict[str, Any]:
    """Defensive length/range clamps so harmless overruns do not cost a retry."""
    out = dict(data)
    out["followup_question"] = _limit(out.get("followup_question"), 240)
    out["rationale"] = _limit(out.get("rationale"), 200)
    ambiguities = out.get("ambiguities")
    if isinstance(ambiguities, list):
        out["ambiguities"] = [str(a)[:200] for a in ambiguities[:5]]
    elif ambiguities is None:
        out["ambiguities"] = []
    conf = out.get("confidence")
    if isinstance(conf, int | float) and not isinstance(conf, bool):
        out["confidence"] = min(1.0, max(0.0, float(conf)))
    target = out.get("target")
    if isinstance(target, dict):
        out["target"] = {**target, "hint": _limit(target.get("hint"), 120)}
    return out


def _thinking_level(name: str) -> Any:
    from google.genai import types

    try:
        return types.ThinkingLevel(name.strip().upper())
    except ValueError:
        logger.warning("Unknown GEMINI_THINKING_LEVEL %r; using LOW", name)
        return types.ThinkingLevel.LOW


def _map_sdk_error(exc: Exception) -> LLMError:
    """Translate any SDK/transport failure to a fixed, key-free message."""
    code = getattr(exc, "code", None)
    if isinstance(exc, httpx.TimeoutException):
        return LLMError("Gemini request timed out")
    if isinstance(exc, httpx.HTTPError):
        return LLMError("Could not reach Gemini")
    if code in (401, 403):
        return LLMError("Gemini rejected the API key or access")
    if code == 404:
        return LLMError("Gemini model not found or unsupported")
    if code == 429:
        return LLMError("Gemini quota or rate limit reached")
    if isinstance(code, int) and code >= 500:
        return LLMError("Gemini service error")
    if isinstance(code, int):
        return LLMError(f"Gemini rejected the request (HTTP {code})")
    return LLMError("Gemini request failed")


class GeminiProvider:
    name = "gemini"

    def __init__(
        self,
        settings: Settings,
        client: GeminiClient | None = None,
        timeout_seconds: float = TOTAL_TIMEOUT_SECONDS,
    ) -> None:
        self.model = settings.gemini_model
        self._api_key = settings.gemini_api_key.get_secret_value().strip()
        self._thinking_level = settings.gemini_thinking_level
        self._timeout_seconds = timeout_seconds
        self._client: GeminiClient | None = client

    # -- client ----------------------------------------------------------------------------
    def _get_client(self) -> GeminiClient:
        if self._client is not None:
            return self._client
        if not self._api_key:
            raise LLMError("Gemini is not configured")
        try:
            from google import genai

            self._client = genai.Client(api_key=self._api_key)
        except Exception:
            raise LLMError("Gemini client could not be created") from None
        return self._client

    def _config(self, remaining_seconds: float) -> Any:
        from google.genai import types

        return types.GenerateContentConfig(
            system_instruction=SYSTEM_PROMPT,
            response_mime_type="application/json",
            response_json_schema=RESPONSE_SCHEMA,
            thinking_config=types.ThinkingConfig(thinking_level=_thinking_level(self._thinking_level)),
            max_output_tokens=MAX_OUTPUT_TOKENS,
            http_options=types.HttpOptions(timeout=max(1000, int(remaining_seconds * 1000))),
        )

    # -- main entry ------------------------------------------------------------------------
    def analyse(self, user_message: str, context: LLMContext) -> AgentTurn:
        client = self._get_client()
        prompt = build_user_prompt(user_message, context)
        deadline = time.monotonic() + self._timeout_seconds
        contents: Any = prompt
        problem = ""
        for attempt in (1, 2):
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise LLMError("Gemini request timed out")
            if attempt == 2:
                contents = f"{prompt}\n\n{CORRECTION_TEMPLATE.format(problem=problem)}"
            try:
                response = client.models.generate_content(
                    model=self.model, contents=contents, config=self._config(remaining)
                )
            except LLMError:
                raise
            except Exception as exc:
                error = _map_sdk_error(exc)
                logger.warning("Gemini call failed: %s (%s)", error, type(exc).__name__)
                raise error from None
            try:
                return self._parse(getattr(response, "text", None))
            except _InvalidOutput as invalid:
                problem = invalid.problem
                logger.warning("Gemini output invalid (attempt %d): %s", attempt, problem)
        raise LLMOutputError("Gemini returned an invalid structured response")

    @staticmethod
    def _parse(text: str | None) -> AgentTurn:
        if not text or not text.strip():
            raise _InvalidOutput("empty response")
        try:
            data = json.loads(_strip_fences(text))
        except ValueError:
            raise _InvalidOutput("not valid JSON") from None
        if not isinstance(data, dict):
            raise _InvalidOutput("JSON root is not an object")
        try:
            return AgentTurn.model_validate(normalise_output(data))
        except ValidationError as exc:
            # Only field paths (never values) go into the corrective hint and the log.
            fields = sorted({".".join(str(p) for p in e["loc"]) or "root" for e in exc.errors()})
            raise _InvalidOutput("invalid fields: " + ", ".join(fields[:6])) from None


class _InvalidOutput(Exception):
    def __init__(self, problem: str) -> None:
        super().__init__(problem)
        self.problem = problem
