_CURRENCY_CODES = {"hkd", "usd", "eur", "gbp", "jpy", "cny", "rmb", "sgd", "aud", "cad"}
_AMOUNT_PRE = re.compile(
    r"(?<![\w.])(hk\$|us\$|\$|hkd|usd|eur|gbp|jpy|cny|rmb|sgd|aud|cad)\s*(\d[\d,]*(?:\.\d+)?)"
